emit "effective-config" 'CID=$(docker ps --format "{{.ID}} {{.Image}}" 2>/dev/null | grep -iE "vllm" | head -1 | awk '\''{print $1}'\''); if [ -n "${CID:-}" ]; then echo "--- 引擎自报有效配置（容器日志里的 Initializing 行，最能反映真正生效的配置）:"; docker logs "$CID" 2>&1 | grep -m2 -A3 -E "Initializing a V1 LLM engine|Initializing an LLM engine" | head -c 6000; echo; echo "--- 该行里的关键字段:"; docker logs "$CID" 2>&1 | grep -m1 -oE "(speculative_config|quantization|kv_cache_dtype|max_seq_len|tensor_parallel_size|data_parallel_size|enable_prefix_caching|enable_chunked_prefill|block_size|enforce_eager|dtype)=[^,]*" | head -20; else echo "DSH-SIGNAL effective_config=unavailable(未找到容器)"; fi'
emit "metrics-full" 'EP="${VLLM_BASE:-http://127.0.0.1:8000}"; M="${MODEL_NAME:-}"; [ -z "$M" ] && M=$(timeout 10 curl -s --connect-timeout 3 --max-time 30 "$EP/v1/models" | grep -o '\''"id":"[^"]*"'\'' | head -1 | cut -d'\''"'\'' -f4); echo "DSH-SIGNAL metrics.model=$M"; ALL=$(timeout 30 curl -s --connect-timeout 3 --max-time 25 "$EP/metrics" 2>/dev/null); if [ -z "$ALL" ]; then echo "DSH-SIGNAL metrics.unavailable=true（/metrics 无响应：该部署可能未暴露指标端点）"; else echo "DSH-SIGNAL metrics.family_count=$(printf '\''%s'\'' "$ALL" | grep -c '\''^vllm:'\'')"; echo "--- 指标族清单（不带标签，用于确认哪些证据可采）:"; printf '\''%s'\'' "$ALL" | grep -E '\''^vllm:'\'' | sed '\''s/{.*//'\'' | sort -u | head -70; echo "--- 草稿/接受率（H-B 直接证据链）:"; printf '\''%s'\'' "$ALL" | grep -E '\''^vllm:spec_decode'\'' | head -30; echo "--- 队列/KV/调度（H-C 直接证据链）:"; printf '\''%s'\'' "$ALL" | grep -E '\''^vllm:(num_preemptions_total|num_requests_running|num_requests_waiting|kv_cache_usage_perc|gpu_cache_usage_perc|prefix_cache_(queries|hits)_total|max_num_seqs)'\'' | head -40; echo "--- 延迟与吞吐:"; printf '\''%s'\'' "$ALL" | grep -E '\''^vllm:(time_to_first_token_seconds_(sum|count)|e2e_request_latency_seconds_(sum|count)|request_success_total)'\'' | head -30; echo "--- 失败/中止类（若有）:"; printf '\''%s'\'' "$ALL" | grep -Ei '\''^vllm:.*(fail|error|abort|cancel|reject|drop)'\'' | head -20; fi'
emit "evidence-gaps" 'echo "DSH-SIGNAL evidence.available.0=effective_config（引擎自报生效配置：容器日志 Initializing 行）"; echo "DSH-SIGNAL evidence.available.1=metrics（/metrics 指标族，含 spec_decode/抢占/缓存/延迟）"; echo "DSH-SIGNAL evidence.available.2=weights_and_tokenizer（分片数与指纹）"; EP="${VLLM_BASE:-http://127.0.0.1:8000}"; if timeout 15 curl -s --connect-timeout 3 --max-time 10 "$EP/metrics" 2>/dev/null | grep -q '\''^vllm:'\''; then echo "DSH-SIGNAL evidence.available.3=metrics_endpoint=ok"; else echo "DSH-SIGNAL evidence.missing.0=metrics_endpoint（/metrics 不可达 → 无法用指标做时间/计数关联）"; fi; CID=$(docker ps --format "{{.ID}} {{.Image}}" 2>/dev/null | grep -iE "vllm" | head -1 | awk '\''{print $1}'\''); if [ -n "${CID:-}" ]; then if docker logs --tail 200 "$CID" 2>&1 | grep -qE '\''SamplingParams|Received request'\''; then echo "DSH-SIGNAL evidence.available.4=request_params（日志含请求级参数）"; else echo "DSH-SIGNAL evidence.missing.1=client_request_params（服务未开 --enable-log-requests → 看不到客户端 temperature/惩罚/max_tokens；这是许多假设无法判定的根本原因）"; fi; else echo "DSH-SIGNAL evidence.missing.2=container（未定位到容器）"; fi; echo "DSH-SIGNAL evidence.missing.3=response_body（vLLM 不落响应正文；若无法取到网关/平台记录或客户端留痕，则'\''输出内容是否正确'\''在原理上无法从服务端日志判定——这一点必须显式声明，不能靠推理补全）"; echo "DSH-SIGNAL evidence.missing.4=per_request_binding（指标为聚合值，无法把单个坏样本绑定到具体 engine/rank；需要 -—collect-detailed-traces 或网关 request_id 才能建立绑定）"'
emit "engine-log" 'CID=$(docker ps --format "{{.ID}} {{.Image}}" 2>/dev/null | grep -iE "vllm" | head -1 | awk '\''{print $1}'\''); if [ -z "${CID:-}" ]; then echo "DSH-SIGNAL engine_log=unavailable(未定位到容器)"; else LOGS=$(docker exec "$CID" sh -c '\''ls -1 /workspace/*.log /root/*.log /tmp/*.log /app/*.log 2>/dev/null | head -5'\'' 2>/dev/null); if [ -z "$LOGS" ]; then LOGS=$(docker exec "$CID" sh -c '\''find / -maxdepth 3 -name "*.log" 2>/dev/null | head -5'\'' 2>/dev/null); fi; N=0; for L in $LOGS; do N=$((N+1)); done; echo "DSH-SIGNAL engine_log.files=$N"; for L in $LOGS; do echo "--- engine-log: $L"; echo "--- [启动期] 生效配置字段:"; docker exec "$CID" sh -c "head -n 500 '\''$L'\''" 2>/dev/null | grep -aE "Initializing|with config|speculative_config|quantization=|kv_cache_dtype=|max_seq_len=|enable_prefix_caching|enable_chunked_prefill|tensor_parallel_size=|data_parallel_size=|block_size=|sliding_window|dtype=" | head -30; echo "--- [尾部 3000 行] 请求级参数/调度统计/告警:"; docker exec "$CID" sh -c "tail -n 3000 '\''$L'\''" 2>/dev/null | grep -aE "SamplingParams|Received request|Added request|Prefix cache hit rate|Avg prompt throughput|Running: |Waiting: |preempt|abort|WARNING|ERROR|Traceback|NaN|Inf|fallback|unsupported|accepted" | tail -n 150; done; fi'
emit "logits-probe" 'EP="${VLLM_BASE:-http://127.0.0.1:8000}"; M="${MODEL_NAME:-}"; [ -z "$M" ] && M=$(timeout 10 curl -s --connect-timeout 3 --max-time 30 "$EP/v1/models" | grep -o '\''"id":"[^"]*"'\'' | head -1 | cut -d'\''"'\'' -f4); echo "DSH-SIGNAL logits.model=$M"; TS=$(date +%s); A="probeA-$TS"; B="probeB-$TS"; one(){ timeout 180 curl -s --connect-timeout 3 --max-time 150 "$EP/v1/chat/completions" -H '\''Content-Type: application/json'\'' -d "{\"model\":\"$M\",\"messages\":[{\"role\":\"user\",\"content\":\"用一句话说明什么是张量并行。\"}],\"temperature\":0,\"seed\":7,\"max_tokens\":1,\"logprobs\":true,\"top_logprobs\":5$1}" 2>&1; }; t0=$(date +%s); R1=$(one ",\"cache_salt\":\"$A\""); t1=$(date +%s); R2=$(one ",\"cache_salt\":\"$A\""); t2=$(date +%s); R3=$(one ",\"cache_salt\":\"$B\""); t3=$(date +%s); echo "DSH-SIGNAL logits.salt_supported=$(printf '\''%s'\'' "$R1" | grep -c cache_salt)"; rd(){ printf '\''%s'\'' "$1" | python3 -c "import json,sys;d=json.load(sys.stdin);c=d['\''choices'\''][0];lp=c.get('\''logprobs'\'') or {};cs=(lp.get('\''content'\'') or [{}])[0];t5=cs.get('\''top_logprobs'\'') or [];print('\''tok=%r lp=%s top5=%s ptok=%s'\'' % (cs.get('\''token'\''), cs.get('\''logprob'\''), '\'','\''.join('\''%s:%s'\''%(x.get('\''token'\''),x.get('\''logprob'\'')) for x in t5[:5]), (d.get('\''usage'\'') or {}).get('\''prompt_tokens'\'')))" 2>/dev/null || echo '\''<无法解析：'\''$(printf '\''%s'\'' "$1" | head -c 160)'\''>'\''; }; echo "--- [路径1 完整重算#1 salt=$A] $(rd "$R1") 耗时$((t1-t0))s"; echo "--- [路径2 同salt命中]      $(rd "$R2") 耗时$((t2-t1))s"; echo "--- [路径3 换salt完整重算#2] $(rd "$R3") 耗时$((t3-t2))s"; C1=$(printf '\''%s'\'' "$R1" | python3 -c "import json,sys;d=json.load(sys.stdin);print((d['\''choices'\''][0].get('\''logprobs'\'') or {}).get('\''content'\'',[{}])[0].get('\''logprob'\''))" 2>/dev/null); C3=$(printf '\''%s'\'' "$R3" | python3 -c "import json,sys;d=json.load(sys.stdin);print((d['\''choices'\''][0].get('\''logprobs'\'') or {}).get('\''content'\'',[{}])[0].get('\''logprob'\''))" 2>/dev/null); if [ -z "$C1" ] || [ -z "$C3" ]; then echo "DSH-SIGNAL logits.prefill_repeat_consistent=n/a (端点未返回可解析的 logprobs：**不下结论**，不把失败当成漂移)"; elif [ "$C1" = "$C3" ]; then echo "DSH-SIGNAL logits.prefill_repeat_consistent=true（两次完整重算首 token logprob 相同 → 采样前无漂移）"; else echo "DSH-SIGNAL logits.prefill_repeat_consistent=false（两次完整重算首 token logprob 不同 → **采样前已漂移**：这是比文本乱码强得多的判据，直接指向长 prefill 计算/地址路径）"; fi'
emit "index-address-probe" 'CID=$(docker ps --format "{{.ID}} {{.Image}}" 2>/dev/null | grep -iE "vllm" | head -1 | awk '\''{print $1}'\''); if [ -n "${CID:-}" ]; then echo "--- 物理 block/页号相关能力（溢出类根因的可算判据）:"; docker exec "$CID" sh -c '\''python3 -c "import vllm,torch;print(1)"'\'' >/dev/null 2>&1 && echo '\''DSH-SIGNAL num_blocks.collect=可执行（容器内 python 可用）'\''; timeout 20 curl -s --connect-timeout 3 --max-time 15 "${VLLM_BASE:-http://127.0.0.1:8000}/metrics" 2>/dev/null | grep -E '\''^vllm:(num_gpu_blocks|kv_cache|gpu_cache)'\'' | head -5; echo '\''提示：索引/地址类根因需要现场补充「每块 key-scale 的跨度」与最大物理页号（判据：2^31 除以该跨度取整 +1 是否被触及）'\''; else echo '\''DSH-SIGNAL num_blocks.collect=unavailable'\''; fi'
emit "perf-snapshot" 'EP="${VLLM_BASE:-http://127.0.0.1:8000}"; ME="${MINDIE_ENDPOINT:-}"; [ -n "$ME" ] && EP="${ME%/v1/chat/completions}"; M="${MODEL_NAME:-}"; [ -z "$M" ] && M=$(timeout 10 curl -s --connect-timeout 3 --max-time 8 "$EP/v1/models" 2>/dev/null | grep -o "\"id\":\"[^\"]*\"" | head -1 | cut -d"\"" -f4); if [ -z "$M" ]; then echo "DSH-SIGNAL perf.unavailable=true (端点无 /v1/models 响应：未测到任何性能指标，不臆断)"; else CH="$EP/v1/chat/completions"; P="[{\"role\":\"user\",\"content\":\"用一句话说明什么是张量并行。\"}]"; echo "DSH-SIGNAL perf.model=$M"; echo "DSH-SIGNAL perf.max_tokens=64"; T0=$(date +%s%3N); R=$(timeout 120 curl -s --connect-timeout 3 --max-time 90 "$CH" -H "Content-Type: application/json" -d "{\"model\":\"$M\",\"messages\":$P,\"temperature\":0,\"max_tokens\":64,\"seed\":7}" 2>&1); if [ "$(printf "%s" "$R" | grep -c "choices")" = "0" ]; then echo "DSH-SIGNAL perf.unavailable=true (端点响应无 choices：**未做任何计时/计数**，不臆断)"; else T1=$(date +%s%3N); E2E=$((T1-T0)); echo "DSH-SIGNAL perf.e2e_ms=$E2E"; CT=$(printf "%s" "$R" | python3 -c "import json,sys;d=json.load(sys.stdin);u=d.get(\"usage\") or {};print(u.get(\"completion_tokens\",\"\"))" 2>/dev/null); [ -n "$CT" ] && echo "DSH-SIGNAL perf.completion_tokens=$CT"; FT=""; timeout 90 curl -s -N --connect-timeout 3 --max-time 80 "$CH" -H "Content-Type: application/json" -d "{\"model\":\"$M\",\"messages\":$P,\"temperature\":0,\"max_tokens\":64,\"stream\":true,\"seed\":7}" 2>/dev/null | while IFS= read -r L; do if [ -z "$FT" ]; then case "$L" in *content*) FT=$(date +%s%3N); echo "DSH-SIGNAL perf.ttft_ms=$((FT-T0))";; esac; fi; done; fi; MM=$(timeout 20 curl -s --connect-timeout 3 --max-time 15 "$EP/metrics" 2>/dev/null); if [ -n "$MM" ]; then KV=$(printf "%s" "$MM" | grep -m1 "^vllm:gpu_cache_usage_perc" | grep -o "[0-9.]*$"); [ -n "$KV" ] && echo "DSH-SIGNAL perf.kv_cache_usage=$KV"; PH=$(printf "%s" "$MM" | grep -m1 "^vllm:prefix_cache_hits_total" | grep -o "[0-9.]*$"); PQ=$(printf "%s" "$MM" | grep -m1 "^vllm:prefix_cache_queries_total" | grep -o "[0-9.]*$"); [ -n "$PH" ] && [ -n "$PQ" ] && [ "$PQ" != "0" ] && python3 -c "print(\"DSH-SIGNAL perf.prefix_cache_hit_rate=%.4f\" % ($PH/$PQ))"; NP=$(printf "%s" "$MM" | grep -m1 "^vllm:num_preemptions_total" | grep -o "[0-9.]*$"); [ -n "$NP" ] && echo "DSH-SIGNAL perf.num_preemptions=$NP"; else echo "DSH-SIGNAL perf.metrics=unavailable"; fi; fi; true'
emit "container-state" 'if command -v docker >/dev/null 2>&1; then docker ps -a --format '\''{{.Names}} {{.Status}} {{.Image}}'\''; else echo "DSH-SIGNAL docker.cli=unavailable (在容器内执行：宿主机上跑本脚本才能采到容器证据)"; fi'
emit "container-log" 'if command -v docker >/dev/null 2>&1; then docker logs --tail 300 $(docker ps -lq); else echo "DSH-SIGNAL docker.cli=unavailable (在容器内执行：宿主机上跑本脚本才能采到容器证据)"; fi'
emit "container-state" 'if command -v docker >/dev/null 2>&1; then docker inspect $(docker ps -lq) --format '\''{{.HostConfig.Memory}} {{.HostConfig.ShmSize}}'\''; else echo "DSH-SIGNAL docker.cli=unavailable (在容器内执行：宿主机上跑本脚本才能采到容器证据)"; fi'
emit "nv-device" 'if command -v nvidia-smi >/dev/null 2>&1; then echo "DSH-SIGNAL nv.smi.available=true"; nvidia-smi 2>&1 | head -40; else echo "DSH-SIGNAL nv.smi.available=false (nvidia-smi 不存在：容器内未挂驱动工具或非 NVIDIA 宿主)"; fi'
emit "nv-driver-matrix" 'if command -v nvidia-smi >/dev/null 2>&1; then echo "DSH-SIGNAL nv.driver.version=$(nvidia-smi --query-gpu=driver_version --format=csv,noheader 2>/dev/null | head -1)"; echo "DSH-SIGNAL nv.gpu.name=$(nvidia-smi --query-gpu=name --format=csv,noheader 2>/dev/null | head -1)"; echo "DSH-SIGNAL nv.compute_cap=$(nvidia-smi --query-gpu=compute_cap --format=csv,noheader 2>/dev/null | head -1)"; echo "DSH-SIGNAL nv.memory.total=$(nvidia-smi --query-gpu=memory.total --format=csv,noheader 2>/dev/null | head -1)"; cat /proc/driver/nvidia/version 2>/dev/null | head -3 || echo "DSH-SIGNAL nv.proc.version=missing"; else echo "DSH-SIGNAL nv.driver.matrix=unavailable"; fi'
emit "nv-ecc" 'if command -v nvidia-smi >/dev/null 2>&1; then nvidia-smi -q -d ECC 2>&1 | grep -aE "ECC Mode|Volatile|Aggregate|Uncorrectable|Corrected|N/A" | head -40; else echo "DSH-SIGNAL nv.ecc=unavailable"; fi'
emit "nv-thermal" 'if command -v nvidia-smi >/dev/null 2>&1; then S=${THERMAL_SAMPLES:-6}; I=${THERMAL_INTERVAL:-10}; echo "DSH-SIGNAL nv.thermal.samples=$S interval=${I}s"; for i in $(seq 1 "$S"); do nvidia-smi --query-gpu=temperature.gpu,clocks_throttle_reasons.active,power.draw --format=csv,noheader 2>&1; sleep "$I"; done; else echo "DSH-SIGNAL nv.thermal=unavailable"; fi'
emit "kernel-log" 'dmesg 2>/dev/null | grep -aE "NVRM|Xid|nvrm" | tail -n 120 || echo "DSH-SIGNAL nv.xid=unavailable (dmesg 需 root 或权限受限)"'
emit "nv-topology" 'if command -v nvidia-smi >/dev/null 2>&1; then nvidia-smi topo -m 2>&1 | head -20; nvidia-smi --query-compute-apps=pid,process_name,used_memory --format=csv 2>&1 | head -20; else echo "DSH-SIGNAL nv.topology=unavailable"; fi'
emit "kernel-log" 'dmesg 2>/dev/null | tail -n 300 || echo "DSH-SIGNAL kernel.log=unavailable (dmesg 需 root 或权限受限)"'
emit "host-mem" 'echo "DSH-SIGNAL mem.total_kb=$(awk '\''/^MemTotal:/{print $2}'\'' /proc/meminfo 2>/dev/null)"; echo "DSH-SIGNAL mem.available_kb=$(awk '\''/^MemAvailable:/{print $2}'\'' /proc/meminfo 2>/dev/null)"; echo "DSH-SIGNAL mem.swap_total_kb=$(awk '\''/^SwapTotal:/{print $2}'\'' /proc/meminfo 2>/dev/null)"; free -m 2>/dev/null | head -4; head -5 /proc/meminfo 2>/dev/null'
emit "host-limits" 'echo "DSH-SIGNAL ulimit.nofile=$(ulimit -n 2>/dev/null)"; echo "DSH-SIGNAL ulimit.nproc=$(ulimit -u 2>/dev/null)"; echo "DSH-SIGNAL cgroup.memory.max=$(cat /sys/fs/cgroup/memory.max 2>/dev/null || cat /sys/fs/cgroup/memory/memory.limit_in_bytes 2>/dev/null || echo unknown)"; echo "DSH-SIGNAL cgroup.memory.current=$(cat /sys/fs/cgroup/memory.current 2>/dev/null || echo unknown)"; df -h 2>/dev/null | head -12'

T1=$(date +%s)
echo "[$(date +%H:%M:%S)] 完成：报告写入 $OUT（本机已脱敏，明文不落盘）；总耗时 $((T1-T0)) 秒。" >&2
echo "        请把 $OUT 整份贴回（可先跑 tail -5 确认结尾是 '=== end:kernel-log ==='）。" >&2
